import XCTest
final class ProbeTests:XCTestCase {
 func tap(_ app:XCUIApplication,_ name:String){let q=app.buttons.matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:12),app.debugDescription);if q.count==1{q.firstMatch.tap();return};guard let b=q.allElementsBoundByIndex.first(where:{$0.isHittable})else{XCTFail("No hittable button "+name);return};b.tap()}
 func option(_ app:XCUIApplication,_ name:String){let q=app.descendants(matching:.any).matching(identifier:name);XCTAssertTrue(q.firstMatch.waitForExistence(timeout:10),app.debugDescription);q.firstMatch.tap()}
 func testGuestApplyLoginProfileReturnsWithoutSending() throws {
 continueAfterFailure=false
 let app=XCUIApplication(bundleIdentifier:"com.example.fancy.dev");app.launch();let decline=app.buttons["Decline analytics"];if decline.waitForExistence(timeout:2){decline.tap()}
 let meal=app.buttons.matching(NSPredicate(format:"label BEGINSWITH %@","QA AI browser future meal,")).firstMatch;XCTAssertTrue(meal.waitForExistence(timeout:12),app.debugDescription);meal.tap();tap(app,"Request to join");tap(app,"Continue with email");let email=app.textFields["Email address"];XCTAssertTrue(email.waitForExistence(timeout:10));email.tap();email.typeText("qa-ai-native70@example.invalid");tap(app,"Send code");let code=app.textFields["6-digit code"];XCTAssertTrue(code.waitForExistence(timeout:12),app.debugDescription);code.tap();code.typeText("000000");tap(app,"Verify & continue");let name=app.textFields["First name"];XCTAssertTrue(name.waitForExistence(timeout:12),app.debugDescription);name.tap();name.typeText("QA Native AI");let bio=app.textViews["A little about you"];bio.tap();bio.typeText("A synthetic neighbour for independent AI application testing.");app.swipeUp();option(app,"New to London");option(app,"English");option(app,"Food");option(app,"I’m 18 or older and I’ll keep this community welcoming, respectful and friendship-first.");tap(app,"Take your seat");let intro=app.textViews["Your introduction"];XCTAssertTrue(intro.waitForExistence(timeout:12),app.debugDescription);XCTAssertEqual(intro.value as? String,"");XCTAssertTrue(app.buttons["Send request"].exists);print("QA_NATIVE70_GUEST_PREFIX_RETURNED_WITHOUT_SEND\n"+app.debugDescription);let a=XCTAttachment(screenshot:app.screenshot());a.name="native70-guest-prefix-original-apply";a.lifetime = .keepAlways;add(a)
 }
}
